// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReservoirPegStabilityModule} from "./ReservoirPegStabilityModule.sol";
import {ReservoirSavingModule} from "./ReservoirSavingModule.sol";
import {ReservoirCreditEnforcer} from "./ReservoirCreditEnforcer.sol";

contract ReservoirSwap {
    using SafeERC20 for IERC20;

    IERC20 private immutable token;
    IERC20 private immutable usdc;
    IERC20 private immutable savingToken;
    ReservoirSavingModule private immutable savingModule;
    ReservoirPegStabilityModule private immutable psm;
    ReservoirCreditEnforcer private immutable creditEnforcer;

    constructor(IERC20 _token, IERC20 _usdc, IERC20 _savingToken, ReservoirSavingModule _savingModule, ReservoirPegStabilityModule _psm, ReservoirCreditEnforcer _creditEnforcer) {
        token = _token;
        usdc = _usdc;
        savingToken = _savingToken;
        savingModule = _savingModule;
        psm = _psm;
        creditEnforcer = _creditEnforcer;
    }

    function swapSavingsToUSDC(uint amount) external {
        savingToken.safeTransferFrom(msg.sender, address(this), amount);

        uint price = savingModule.currentPrice();
        uint fee = savingModule.redeemFee();
        uint rUsdAmount = amount * price / (100 * (1000000 + fee));
        _approveSwap(savingToken, address(savingModule));
        savingModule.redeem(rUsdAmount);

        uint outAmount = rUsdAmount / 10 ** 12;
        _approveSwap(token, address(psm));
        psm.redeem(outAmount);

        _transferChange(usdc, 10000);
        _transferChange(token, 10000000000000000);
        _transferChange(savingToken, 10000000000000000);
    }

    function swapUSDCToSavings(uint amount) external {
        usdc.safeTransferFrom(msg.sender, address(this), amount);
        _approveSwap(usdc, address(psm));
        creditEnforcer.mintStablecoin(amount);

        _approveSwap(token, address(savingModule));
        creditEnforcer.mintSavingcoin(amount * 10 ** 12);

        _transferChange(usdc, 10000);
        _transferChange(token, 10000000000000000);
        _transferChange(savingToken, 10000000000000000);
    }

    function _transferChange(IERC20 _token, uint minimal) internal {
        uint balance = _token.balanceOf(address(this));
        if (balance > minimal) {
            _token.safeTransfer(msg.sender, balance);
        }
    }

    function _approveSwap(IERC20 token0, address exchange) internal {
        if (token0.allowance(address(this), address(exchange)) == 0) {
            token0.forceApprove(exchange, type(uint256).max);
        }
    }
}

contracts/reservoir/ReservoirWsrUsdZap.s.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "./ReservoirPegStabilityModule.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IERC4626 is IERC20 {
    function deposit(uint256 assets, address receiver) external returns (uint256 shares);
    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assets);
}

interface IReservoirCreditEnforcer {
    function mintStablecoin(uint256 amount) external;
}

contract ReservoirWsrUsdZap {
    using SafeERC20 for IERC20;

    IERC20 public immutable usdc;
    IERC20 public immutable rUsd;
    IERC4626 public immutable wsrUsd;
    ReservoirPegStabilityModule public immutable psm;
    IReservoirCreditEnforcer public immutable creditEnforcer;

    constructor(
        IERC20 _usdc,
        IERC20 _rUsd,
        IERC4626 _wsrUsd,
        ReservoirPegStabilityModule _psm,
        IReservoirCreditEnforcer _creditEnforcer
    ) {
        usdc = _usdc;
        rUsd = _rUsd;
        wsrUsd = _wsrUsd;
        psm = _psm;
        creditEnforcer = _creditEnforcer;
    }

    function swapUSDCToWsrUSD(uint256 amount, uint256 minShares) external returns (uint256 sharesOut) {
        usdc.safeTransferFrom(msg.sender, address(this), amount);

        _approveIfNeeded(usdc, address(psm));

        creditEnforcer.mintStablecoin(amount);

        uint256 rUsdBalance = rUsd.balanceOf(address(this));
        require(rUsdBalance > 0, "No rUSD minted");

        _approveIfNeeded(rUsd, address(wsrUsd));
        sharesOut = wsrUsd.deposit(rUsdBalance, msg.sender);
        require(sharesOut >= minShares, "Slippage wsrUSD");

        _transferDust(usdc, msg.sender, 10_000);              // ~0.01 USDC
        _transferDust(rUsd, msg.sender, 1e12);                 // ~0.000001 rUSD
        _transferDust(IERC20(address(wsrUsd)), msg.sender, 1); // минимальный дст по wsrUSD

        return sharesOut;
    }

    function swapWsrUSDToUSDC(uint256 shares, uint256 minUsdc) external returns (uint256 usdcOut) {
        IERC20(address(wsrUsd)).safeTransferFrom(msg.sender, address(this), shares);

        uint256 rUsdBefore = rUsd.balanceOf(address(this));
        wsrUsd.redeem(shares, address(this), address(this));
        uint256 rUsdDelta = rUsd.balanceOf(address(this)) - rUsdBefore;
        require(rUsdDelta > 0, "No rUSD received");

        uint256 usdcAmount = rUsdDelta / 1e12;
        require(usdcAmount > 0, "Too small amount");

        _approveIfNeeded(rUsd, address(psm));
        psm.redeem(usdcAmount);

        usdcOut = usdc.balanceOf(address(this));
        require(usdcOut >= minUsdc, "Slippage USDC");

        usdc.safeTransfer(msg.sender, usdcOut);

        _transferDust(rUsd, msg.sender, 1e12);
        _transferDust(IERC20(address(wsrUsd)), msg.sender, 1);

        return usdcOut;
    }

    function _approveIfNeeded(IERC20 token, address spender) internal {
        if (token.allowance(address(this), spender) == 0) {
            token.forceApprove(spender, type(uint256).max);
        }
    }

    function _transferDust(IERC20 token, address to, uint256 minAmount) internal {
        uint256 bal = token.balanceOf(address(this));
        if (bal > minAmount) {
            token.safeTransfer(to, bal);
        }
    }
}

