// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "../util/StorageUtil.sol";
import "@aave/core-v3/contracts/interfaces/IPool.sol";
import "@aave/core-v3/contracts/interfaces/IPoolAddressesProvider.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {HasOperation} from "./HasOperation.sol";

contract AaveFlashLoanStrategy is HasOperation {
    using SafeERC20 for IERC20;

    bytes32 private constant FLASH_LOAN_OUT_SLOT = keccak256("flashLoan#output");

    IPoolAddressesProvider private immutable ADDRESSES_PROVIDER;
    IPool private immutable POOL;

    // Event emitted when a flash loan is executed
    event FlashLoanRequested(address token, uint256 amount);

    constructor(address provider) {
        ADDRESSES_PROVIDER = IPoolAddressesProvider(provider);
        POOL = IPool(IPoolAddressesProvider(provider).getPool());
    }

    function getAaveAddressProvider() external view returns (address) {
        return address(ADDRESSES_PROVIDER);
    }

    function getAavePool() external view returns (address) {
        return address(POOL);
    }

    /**
     * @notice Execute a flash loan and pass through the raw callback data
     * @dev Called via delegatecall from the vault
     * @param token The token to flash loan
     * @param amount The amount to borrow
     * @param operations operation list for the vault (when flashloan received)
     * @return out output which was got during flash loan operation
     */
    function executeFlashLoan(
        address token,
        uint256 amount,
        Operation[] calldata operations
    ) external returns (uint out) {
        // Execute the flash loan with the provided raw data
        POOL.flashLoanSimple(
            address(this),
            token,
            amount,
            abi.encode(operations),
            0
        );
        out = StorageUtil.readUintSlot(FLASH_LOAN_OUT_SLOT);
        StorageUtil.setUintSlot(FLASH_LOAN_OUT_SLOT, 0);

        emit FlashLoanRequested(token, amount);
    }
}

contracts/vault/AaveStrategy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@aave/core-v3/contracts/interfaces/IPool.sol";
import "../util/StorageUtil.sol";
import {IPoolDataProvider} from "@aave/core-v3/contracts/interfaces/IPoolDataProvider.sol";

contract AaveStrategy {
    using SafeERC20 for IERC20;

    bytes32 private constant DATA_PROVIDER = "DATA_PROVIDER";

    IPool private immutable AAVE_POOL;
    IERC20 private immutable COLLATERAL_TOKEN;

    constructor(IPoolAddressesProvider addressProvider, address collateralToken) {
        AAVE_POOL = IPool(addressProvider.getPool());
        COLLATERAL_TOKEN = IERC20(collateralToken);
    }

    function init(uint8 category) external {
        AAVE_POOL.setUserEMode(category);
    }

    // ----- main strategy functions ----- //

    function supplyCollateral(uint256 amount) external {
        uint256 supplyAmount;

        // If max uint is passed, supply all available tokens
        if (amount == type(uint256).max) {
            supplyAmount = COLLATERAL_TOKEN.balanceOf(address(this));
        } else {
            supplyAmount = amount;
        }

        require(supplyAmount > 0, "Amount must be greater than 0");
        _approveIfNeeded(address(COLLATERAL_TOKEN), address(AAVE_POOL), supplyAmount);
        _depositCollateral(supplyAmount);
    }

    function withdrawCollateral(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        _withdrawCollateral(amount);
    }

    function borrowDebt(address token, uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        _borrow(token, amount);
    }

    function repayDebt(address token, uint256 amount) external {
        IPoolDataProvider dataProvider = _readPoolDataProvider();
        uint borrowBalance = _getDebtAmount(dataProvider, token);
        require(borrowBalance > 0, "No borrow balance to repay");

        // If amount is max uint256, repay the full balance
        uint256 repayAmount = amount;
        if (amount == type(uint256).max) {
            repayAmount = borrowBalance;
        }

        _approveIfNeeded(token, address(AAVE_POOL), repayAmount);
        _repay(token, repayAmount);
    }
    // ----- aave related functions ----- //

    function _getDebtAmount(IPoolDataProvider dataProvider, address token) internal view returns (uint256 shortAmount) {
        (
        ,                    // currentATokenBalance
        ,                    // currentStableDebt
            shortAmount,     // currentVariableDebt - amount borrowed
        ,                    // principalStableDebt
        ,                    // scaledVariableDebt
        ,                    // stableBorrowRate
        ,                    // liquidityRate
        ,                    // stableRateLastUpdated
        // usageAsCollateralEnabled
        ) = dataProvider.getUserReserveData(token, address(this));
    }

    function _depositCollateral(uint256 amount) internal {
        AAVE_POOL.supply(address(COLLATERAL_TOKEN), amount, address(this), 0);
    }

    function _withdrawCollateral(uint256 amount) internal {
        AAVE_POOL.withdraw(address(COLLATERAL_TOKEN), amount, address(this));
    }

    // @notice Borrows more short token
    function _borrow(address token, uint256 amount) internal {
        AAVE_POOL.borrow(token, amount, 2, 0, address(this)); // Variable rate = 2
    }

    // @notice Repays borrowed short token
    function _repay(address token, uint256 amount) internal {
        AAVE_POOL.repay(token, amount, 2, address(this)); // Variable rate = 2
    }

    function _readPoolDataProvider() internal view returns (IPoolDataProvider) {
        return IPoolDataProvider(AAVE_POOL.ADDRESSES_PROVIDER().getAddress(DATA_PROVIDER));
    }

    function _approveIfNeeded(address token, address spender, uint256 amount) internal {
        uint256 allowance = IERC20(token).allowance(address(this), spender);
        if (allowance < amount) {
            IERC20(token).forceApprove(spender, type(uint256).max);
        }
    }
}

contracts/vault/AutomatedVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@aave/core-v3/contracts/flashloan/interfaces/IFlashLoanSimpleReceiver.sol";
import "@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {DelegateCall} from "../util/DelegateCall.sol";
import {HasOperation} from "./HasOperation.sol";
import {RolesUpgradeable} from "../util/RolesUpgradeable.sol";
import {StorageUtil} from "../util/StorageUtil.sol";

// @notice Vault manages funds. It can have several strategies inside
// @dev Strategy is code-only contract which is called using delegatecall
contract AutomatedVault is HasOperation, IFlashLoanSimpleReceiver, Initializable, ContextUpgradeable, RolesUpgradeable {
    using SafeERC20 for IERC20;

    // Morpho contract address
    address private immutable MORPHO_ADDRESS;
    IPoolAddressesProvider public immutable ADDRESSES_PROVIDER;
    IPool public immutable POOL;

    bytes32 private constant FLASH_LOAN_OUT_SLOT = keccak256("flashLoan#output");

    // @notice list of strategies
    address[] private strategies;

    bool private rebalancing;

    constructor (address _morpho, address aaveProvider) {
        MORPHO_ADDRESS = _morpho;
        ADDRESSES_PROVIDER = IPoolAddressesProvider(aaveProvider);
        POOL = IPool(IPoolAddressesProvider(aaveProvider).getPool());
        _disableInitializers();
    }

    // @notice Initialized the vault. It can have any number of initialization calls for the strategies inside
    function __Vault_init(address[] calldata _strategies) external initializer {
        __Context_init_unchained();
        __RolesUpgradeable_init_unchained();
        __Vault_init_unchained(_strategies);
    }

    function __Vault_init_unchained(address[] calldata _strategies) internal {
        strategies = _strategies;
    }

    // @notice Updates list of strategies
    // @dev Can be called only by owner
    function setStrategies(address[] calldata _strategies) external onlyOwner {
        strategies = _strategies;
    }

    function getStrategies() external view returns (address[] memory) {
        return strategies;
    }

    // @dev Rebalances the vault
    // @return uint value returned from the swap strategy (if it's used)
    function rebalance(Operation[] calldata _operations) external operatorOrOwner returns (uint out) {
        rebalancing = true;
        out = executeOperations(_operations);
        rebalancing = false;
    }

    function executeOperations(Operation[] memory _operations) internal returns (uint out) {
        out = 0;
        for (uint256 i = 0; i < _operations.length; i++) {
            Operation memory _operation = _operations[i];
            bytes memory result = DelegateCall.doDelegateCall(strategies[_operation.position], _operation.callData);

            if (result.length > 0) {
                out = abi.decode(result, (uint256));
            }
        }
    }

    /**
     * @notice Callback function for Morpho flash loans
     * @dev Called by Morpho after sending flash loaned tokens to this contract
     * @param amount The amount that was borrowed
     * @param data Raw bytes data to be used for operations
     */
    function onMorphoFlashLoan(
        uint256 amount,
        bytes calldata data
    ) external {
        // Ensure the caller is the Morpho contract
        address morphoAddress = _getMorphoAddress();
        require(rebalancing, "!NotRebalancing");
        require(msg.sender == morphoAddress, "Caller must be Morpho");

        // Execute operations with the borrowed funds
        // data should be encoded as Operation[] by the caller
        OperationsWithAddress memory received = abi.decode(data, (OperationsWithAddress));
        // state timestamp was checked
        uint out = executeOperations(received.operations);
        StorageUtil.setUintSlot(FLASH_LOAN_OUT_SLOT, out);

        // Transfer tokens back to Morpho to repay the loan
        // This will automatically revert if there aren't enough tokens
        IERC20(received.token).forceApprove(morphoAddress, amount);
    }

    function executeOperation(
        address token,
        uint256 amount,
        uint256 premium,
        address initiator,
        bytes calldata params
    ) external returns (bool) {
        require(rebalancing, "!NotRebalancing");

        require(initiator == address(this));
        // Execute operations with the borrowed funds
        // data should be encoded as Operation[] by the caller
        Operation[] memory operations = abi.decode(params, (Operation[]));
        // state timestamp was checked
        uint out = executeOperations(operations);
        StorageUtil.setUintSlot(FLASH_LOAN_OUT_SLOT, out);

        IERC20(token).forceApprove(address(POOL), amount + premium);
        return true;
    }

    function _getMorphoAddress() internal view returns (address) {
        return MORPHO_ADDRESS;
    }
}

